CREATE SCHEMA IF NOT EXISTS auth; CREATE TABLE IF NOT EXISTS auth.users(id uuid PRIMARY KEY); CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE public.campaign_leads("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"campaign_id" uuid,"lead_id" uuid,"current_step" integer DEFAULT 0,"status" text DEFAULT 'pending'::text,"last_sent_at" timestamptz,"next_send_at" timestamptz,"created_at" timestamptz DEFAULT now());
CREATE TABLE public.campaign_sequences("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"campaign_id" uuid,"step_number" integer NOT NULL,"subject" text NOT NULL,"body_html" text NOT NULL,"body_text" text,"delay_days" integer DEFAULT 1,"delay_hours" integer DEFAULT 0,"condition_type" text DEFAULT 'always'::text,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.campaigns("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"name" text NOT NULL,"status" text DEFAULT 'draft'::text,"settings" jsonb DEFAULT '{"timezone": "America/New_York", "send_days": ["mon", "tue", "wed", "thu", "fri"], "daily_limit": 100, "send_hours_end": 17, "send_hours_start": 9, "max_delay_minutes": 180, "min_delay_minutes": 60}'::jsonb,"stats" jsonb DEFAULT '{"sent": 0, "opened": 0, "bounced": 0, "clicked": 0, "replied": 0}'::jsonb,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.domains("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"domain" text NOT NULL,"registrar" text,"registrar_domain_id" text,"dns_provider" text DEFAULT 'cloudflare'::text,"dns_zone_id" text,"spf_configured" boolean DEFAULT false,"dkim_configured" boolean DEFAULT false,"dkim_selector" text,"dkim_private_key_encrypted" text,"dmarc_configured" boolean DEFAULT false,"bimi_configured" boolean DEFAULT false,"health_status" text DEFAULT 'pending'::text,"last_health_check" timestamptz,"auto_purchased" boolean DEFAULT false,"purchase_price" numeric,"expires_at" timestamptz,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.email_accounts("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"email" text NOT NULL,"display_name" text,"provider" text NOT NULL,"status" text DEFAULT 'active'::text,"smtp_host" text,"smtp_port" integer,"smtp_username" text,"smtp_password_encrypted" text,"imap_host" text,"imap_port" integer,"oauth_tokens_encrypted" jsonb,"daily_limit" integer DEFAULT 50,"sent_today" integer DEFAULT 0,"warmup_enabled" boolean DEFAULT false,"warmup_progress" integer DEFAULT 0,"health_score" integer DEFAULT 100,"last_error" text,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.lead_lists("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"name" text NOT NULL,"description" text,"lead_count" integer DEFAULT 0,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.leads("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"list_id" uuid,"email" text NOT NULL,"first_name" text,"last_name" text,"company" text,"title" text,"phone" text,"linkedin_url" text,"custom_fields" jsonb DEFAULT '{}'::jsonb,"status" text DEFAULT 'active'::text,"validation_status" text,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.organizations("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"name" text NOT NULL,"slug" text NOT NULL,"plan" text DEFAULT 'starter'::text,"stripe_customer_id" text,"stripe_subscription_id" text,"settings" jsonb DEFAULT '{}'::jsonb,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.replies("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"sent_email_id" uuid,"email_account_id" uuid,"lead_id" uuid,"from_email" text NOT NULL,"to_email" text NOT NULL,"subject" text,"body_html" text,"body_text" text,"message_id" text,"in_reply_to" text,"category" text DEFAULT 'uncategorized'::text,"is_read" boolean DEFAULT false,"received_at" timestamptz DEFAULT now(),"created_at" timestamptz DEFAULT now(),"thread_id" uuid,"sentiment" text,"confidence" numeric,"status" text DEFAULT 'received'::text,"mailbox_id" uuid,"from_name" text,"is_auto_detected" boolean DEFAULT false,"snoozed_until" timestamptz);
CREATE TABLE public.sent_emails("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"organization_id" uuid,"campaign_id" uuid,"campaign_lead_id" uuid,"email_account_id" uuid,"lead_id" uuid,"to_email" text NOT NULL,"from_email" text NOT NULL,"subject" text NOT NULL,"body_html" text,"body_text" text,"message_id" text,"status" text DEFAULT 'sent'::text,"opened_at" timestamptz,"clicked_at" timestamptz,"replied_at" timestamptz,"bounced_at" timestamptz,"bounce_type" text,"sent_at" timestamptz DEFAULT now(),"created_at" timestamptz DEFAULT now());
CREATE TABLE public.thread_messages("id" uuid DEFAULT gen_random_uuid() NOT NULL,"thread_id" uuid NOT NULL,"message_id" text,"in_reply_to" text,"direction" text DEFAULT 'inbound'::text NOT NULL,"from_email" text NOT NULL,"from_name" text,"to_email" text NOT NULL,"subject" text,"body_text" text,"body_html" text,"snippet" text,"has_attachments" boolean DEFAULT false,"sent_at" timestamptz DEFAULT now() NOT NULL,"received_at" timestamptz,"created_at" timestamptz DEFAULT now());
CREATE TABLE public.threads("id" uuid DEFAULT gen_random_uuid() NOT NULL,"organization_id" uuid NOT NULL,"mailbox_id" uuid NOT NULL,"campaign_id" uuid,"lead_id" uuid,"thread_external_id" text,"subject" text NOT NULL,"participant_email" text NOT NULL,"participant_name" text,"message_count" integer DEFAULT 1,"last_message_at" timestamptz DEFAULT now(),"first_message_at" timestamptz DEFAULT now(),"status" text DEFAULT 'active'::text,"is_read" boolean DEFAULT false,"category" text DEFAULT 'uncategorized'::text,"sentiment" text,"assigned_to" uuid,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.users("id" uuid NOT NULL,"organization_id" uuid,"email" text NOT NULL,"full_name" text,"role" text DEFAULT 'member'::text,"avatar_url" text,"settings" jsonb DEFAULT '{}'::jsonb,"created_at" timestamptz DEFAULT now(),"updated_at" timestamptz DEFAULT now());
CREATE TABLE public.warmup_emails("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"from_account_id" uuid,"to_account_id" uuid,"message_id" text,"subject" text,"status" text DEFAULT 'sent'::text,"sent_at" timestamptz DEFAULT now(),"opened_at" timestamptz,"replied_at" timestamptz);
